try{await page.getByRole("button",{name:"Search",exact:true}).click();await page.getByRole("option",{name:"Webhooks",exact:true}).click();await page.locator('[data-route-skeleton="webhooks-list"]').waitFor({state:"visible",timeout:15000});for(let j=0;j<150&&!captures.length;j++)await page.waitForTimeout(100);if(!captures.length)throw Error("Real WebhookEndpoints response not captured");const pending=await measure();await page.screenshot({path:"qa-a832-webhooks-pending-${width}.png"});released=true;release();await Promise.allSettled(tasks);await page.getByRole("searchbox",{name:"Search webhooks",exact:true}).waitFor({timeout:15000});await page.waitForTimeout(900);const ready=await measure();await page.screenshot({path:"qa-a832-webhooks-ready-${width}.png"});return{at:new Date().toISOString(),url:page.url(),captures,pending,ready,unchangedResponses:true};}finally{released=true;release();await Promise.allSettled(tasks);await page.unroute(pattern,handler);}
}`}

